contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // Precondition: seed the market so contract is initialized. seedMarket requires marketDrugs==0 on fresh c.
        // call seedMarket with some nonzero drugs and send some Ether to the contract as well
        uint256 seedDrugs = 1000;
        // ensure this contract has enough balance to forward some Ether
        // The checker deploys c and then calls run in a single tx; this contract can receive Ether via payable run
        // We don't require a particular msg.value here; use any value present in this call.
        // If no Ether was sent, still seedMarket is payable but doesn't require Ether; use 0 if none.
        c.seedMarket{value: msg.value}(seedDrugs);

        // record contract balance before calling getFreeKilo
        uint256 beforeBalance = address(c).balance;
        // ensure the caller currently has zero kilos (fresh address should have zero)
        // We cannot assert externally that Kilos[msg.sender]==0 before call in c, but getFreeKilo will revert otherwise.
        bool reverted;
        // call getFreeKilo and capture revert info
        try c.getFreeKilo() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable public values after the call
        uint256 kilos = c.getMyKilo();
        uint256 starting = c.STARTING_KILOS();
        uint256 last = c.lastCollect(address(this));
        uint256 afterBalance = address(c).balance;

        // General rule: if getFreeKilo did NOT revert, then:
        // - caller's kilos equals STARTING_KILOS
        // - lastCollect for caller is nonzero and <= block.timestamp (we cannot call block.timestamp here, but last!=0 suffices for observability)
        // - contract balance unchanged by getFreeKilo (seedMarket may have set it earlier)
        // If it reverted, then kilos must still be 0 and lastCollect must be unchanged (could be 0). We express a single assert combining these.
        assert(
            // either call reverted and state stayed with kilos == 0
            (reverted && kilos == 0)
            ||
            // or call succeeded and kilos == STARTING_KILOS and lastCollect nonzero and contract balance unchanged
            (!reverted && kilos == starting && last != 0 && afterBalance == beforeBalance)
        );
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // amount is the Ether to forward to buyDrugs; must be available in this contract's balance
    function run(uint256 amount) public payable {
