        // Ensure fresh market: seedMarket requires marketDrugs==0 on fresh c
        uint256 seedDrugs = 1000;
        // seedMarket is payable; forward 0 value (no need to send Ether) to initialize marketDrugs
        c.seedMarket{value: 0}(seedDrugs);

        // record contract balance before buy
        uint256 beforeContractBal = address(c).balance;
        // record caller's claimedDrugs before
        uint256 beforeClaimed = c.claimedDrugs(address(this));

        bool reverted;
        try c.buyDrugs{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterContractBal = address(c).balance;
        uint256 afterClaimed = c.claimedDrugs(address(this));

        // When buyDrugs succeeds, the contract's balance must increase by exactly amount
        // and the caller's claimedDrugs must be >= beforeClaimed (since drugsBought added after dev fee)
        // Also, if call reverted then neither observed value should have increased due to the call
        assert(
            (reverted && afterContractBal == beforeContractBal && afterClaimed == beforeClaimed)
            ||
            (!reverted && afterContractBal == beforeContractBal + amount && afterClaimed >= beforeClaimed)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We pass a referral address as an index (0 means address(this)), and we ensure the contract is initialized first.
    function run(uint256 refIndex) public payable {
        // initialize market so collectDrugs won't revert
        // seedMarket requires marketDrugs==0 which holds on fresh c
        c.seedMarket{value: 0}(1000);

        address ref = refIndex == 0 ? address(this) : address(uint160(refIndex));

        // Ensure caller has some claimedDrugs and Kilos so collectDrugs does nontrivial work.
        // Give caller some Kilos via getFreeKilo (requires Kilos==0)
        c.getFreeKilo();

        // Wait a bit by manipulating lastCollect indirectly: we cannot change block.timestamp, but getMyDrugs uses lastCollect; claiming some time passed is not possible here, so we rely on claimedDrugs to hold value.
        // Directly increase claimedDrugs by buying drugs: call buyDrugs with 0 value will likely compute 0, so instead we manually set claimedDrugs via buyDrugs with small value if available.
        // To avoid needing Ether, we keep claimedDrugs as 0 and still check the invariant for the general case (drugsUsed could be 0).

        // record before-values
        uint256 beforeRefClaimed = c.claimedDrugs(ref);
        uint256 beforeMarket = c.marketDrugs();
        uint256 beforeCallerClaimed = c.claimedDrugs(address(this));
        uint256 drugsUsed = c.getMyDrugs(); // observed before-call drugsUsed
        uint256 expectedBonus = drugsUsed / 5;
        uint256 expectedMarketInc = drugsUsed / 10;

        bool reverted;
        try c.collectDrugs(ref) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterRefClaimed = c.claimedDrugs(ref);
        uint256 afterMarket = c.marketDrugs();
        uint256 afterCallerClaimed = c.claimedDrugs(address(this));

        // If collectDrugs reverted then states should be unchanged; otherwise check the claimed/ref/market effects.
        assert(
            (reverted && afterRefClaimed == beforeRefClaimed && afterMarket == beforeMarket && afterCallerClaimed == beforeCallerClaimed)
            ||
            (!reverted && afterRefClaimed >= beforeRefClaimed + expectedBonus && afterMarket >= beforeMarket + expectedMarketInc && afterCallerClaimed == 0)
        );
    }

    receive() external payable { }
}

