        // seed market so sell/buy/collect won't revert due to !initialized
        c.seedMarket{value: 0}(100000);

        // ensure this address has kilos so getMyDrugs > 0 via getFreeKilo
        c.getFreeKilo();

        // To create some claimedDrugs, buyDrugs with payable amountEther
