            c.buyDrugs{value: amountEther}();
        }

        // compute observable before-values
        uint256 beforeContractBal = address(c).balance;
        uint256 beforeCallerBal = address(this).balance;
        uint256 hasDrugs = c.getMyDrugs();
        // If hasDrugs==0 then sell likely returns 0 value; we restrict to hasDrugs>0 to make meaningful assertion
        require(hasDrugs > 0, "no drugs to sell");

        bool reverted;
        try c.sellDrugs() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterContractBal = address(c).balance;
        uint256 afterCallerBal = address(this).balance;

        // drugValue is what the contract would compute for selling hasDrugs; we can recompute via public view
        uint256 drugValue = c.calculateDrugSell(hasDrugs);
        uint256 fee = c.devFee(drugValue);

        // If sellDrugs succeeded then contract balance must have decreased by exactly drugValue
        // (since market receives hasDrugs but ETH paid out equals drugValue, contract ETH decreases by drugValue)
