        uint256 afterClaimed = c.getMyDrugs();
        uint256 afterLast = c.lastCollect(address(this));
        uint256 afterMarket = c.marketDrugs();
        uint256 afterRefClaimed = c.claimedDrugs(ref);

        // If the call reverted, the state must be unchanged for all observed public values
        // Otherwise assert the behavioural invariants of collectDrugs:
        // - caller's claimedDrugs becomes 0 (getMyDrugs() >= getDrugsSinceLastCollect so we check claimed component decreased to be consistent):
        //   We cannot directly read internal claimedDrugs separately from getMyDrugs(), but contract exposes claimedDrugs(ref) mapping and getMyDrugs uses claimedDrugs[msg.sender]+drugsSince. For msg.sender=address(this), drugsSinceLastCollect immediately after call is 0 because lastCollect updated to current timestamp. So getMyDrugs() should equal claimedDrugs[address(this)]. After successful collect, claimedDrugs[address(this)] is set to 0, thus getMyDrugs()==0.
