    constructor(C _c) { c = _c; }

    // We take no ether. The single test function drives getFreeKilo and checks its observable effects.
    // Param: a boolean flag to decide whether to seed the market first (so initialized==true).
    function run(bool seed) public payable {
        // set up: if seed==true, call seedMarket to set initialized=true; provide a nonzero drugs value
        // seedMarket is payable and requires marketDrugs==0 which holds on fresh deployment
        if (seed) {
            // call with some ether and a drugs argument; this changes contract state
            c.seedMarket{value: 0}(1);
        }

        // Read pre-state via public getters
        uint256 kilosBefore = c.getMyKilo();
        // get STARTING_KILOS and initialized via public getters
        uint256 starting = c.STARTING_KILOS();
        bool initialized = c.initialized();
        uint256 lastBefore = c.lastCollect(address(this));

        // Attempt the state-changing call and record whether it reverted
        bool reverted;
        try c.getFreeKilo() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint256 kilosAfter = c.getMyKilo();
        uint256 lastAfter = c.lastCollect(address(this));

        // General rule (single assert): If the call did not revert then initialized must have been true
        // and kilosBefore must have been zero and kilosAfter equals STARTING_KILOS and lastAfter nonzero and >= lastBefore.
        // If the call reverted then at least one of: not initialized OR kilosBefore != 0 must hold.
        assert(
            reverted
            ? (!initialized || kilosBefore != 0)
            : (initialized && kilosBefore == 0 && kilosAfter == starting && lastAfter != 0 && lastAfter >= lastBefore)
        );
    }

    // allow receiving funds to seed market if needed
    receive() external payable {}
}

