contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try buying drugs; parameters: seed (whether to seed market), amount of ETH to send to buyDrugs
    function run(bool doSeed, uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // If needed, seed the market so initialized becomes true. seedMarket is payable and must be called as top-level.
        if (doSeed) {
            c.seedMarket{value: 0}(1);
        }

        // Observe pre-state via public getters
        uint256 claimedBefore = c.claimedDrugs(address(this));
        uint256 contractBalBefore = address(c).balance;
        uint256 ceoBalBefore = c.ceoAddress() == address(0) ? 0 : address(uint160(c.ceoAddress())).balance;
        bool initialized = c.initialized();

        // Perform the state-changing call and capture revert
        bool reverted;
        try c.buyDrugs{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 claimedAfter = c.claimedDrugs(address(this));
        uint256 contractBalAfter = address(c).balance;
        uint256 ceoBalAfter = c.ceoAddress() == address(0) ? 0 : address(uint160(c.ceoAddress())).balance;

        // General property:
        // If the call reverted then either not initialized or some require failed; if it did not revert then initialized must have been true,
        // and the caller's claimedDrugs increased by at least the amount returned by calculateDrugBuySimple(amount) minus devFee on that amount,
        // and the contract balance increased by amount (except for the dev fee forwarded to CEO), i.e., contractBalAfter == contractBalBefore + amount - devFee(msg.value)
        // Because we cannot call internal devFee on the contract directly in a single expression, we use its public devFee view.

        // Build expected values using only public view calls
        uint256 calcBought = c.calculateDrugBuySimple(amount);
        uint256 feeOnBought = c.devFee(calcBought);
        uint256 netExpectedIncrease = 0;
        if (calcBought >= feeOnBought) {
            netExpectedIncrease = calcBought - feeOnBought;
        }

        uint256 feeOnEth = c.devFee(amount);

        // Assert the property
        assert(
            reverted
            ? (!initialized || amount == 0) // if reverted, plausible cause is uninitialized or zero amount (buy might still revert if uninitialized)
            : (
                initialized
                && claimedAfter >= claimedBefore + netExpectedIncrease
                && contractBalAfter + feeOnEth == contractBalBefore + amount
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to seed (if needed) and then call buyDrugs with amount ETH.
    // We require the test contract holds at least `amount` wei to send.
    function run(bool doSeed, uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // If requested, seed the market so initialized becomes true. seedMarket is payable and must be top-level.
        if (doSeed) {
            c.seedMarket{value: 0}(1);
        }

        // Observe pre-state via public getters (only view/public allowed)
        uint256 claimedBefore = c.claimedDrugs(address(this));
        uint256 contractBalBefore = address(c).balance;
        bool initialized = c.initialized();

        // Perform the state-changing call as a top-level statement and capture revert.
        bool reverted;
        try c.buyDrugs{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-state
        uint256 claimedAfter = c.claimedDrugs(address(this));
        uint256 contractBalAfter = address(c).balance;

        // Compute expected net bought drugs using public view
        uint256 calcBought = c.calculateDrugBuySimple(amount);
        uint256 feeOnBought = c.devFee(calcBought);
        uint256 netExpectedIncrease = 0;
        if (calcBought >= feeOnBought) {
            netExpectedIncrease = calcBought - feeOnBought;
        }
        uint256 feeOnEth = c.devFee(amount);

        // General property:
        // If buyDrugs did not revert then initialized must have been true,
        // the caller's claimedDrugs increased by at least netExpectedIncrease,
        // and the contract's balance changed by exactly amount - feeOnEth (fee forwarded to CEO).
        assert(
            reverted
            ? true // if reverted we cannot guarantee post-effects; allow any revert reason
            : (
                initialized
                && claimedAfter >= claimedBefore + netExpectedIncrease
                && contractBalAfter + feeOnEth == contractBalBefore + amount
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run initializes market, gives this contract the free kilos, and checks invariants
    function run(uint256 seedMarketDrugs) public payable {
        require(true);

        // seed the market (only allowed when marketDrugs == 0)
        // seedMarketDrugs can be any value; call must not revert when marketDrugs == 0
        c.seedMarket{value: 0}(seedMarketDrugs);

        // before calling getFreeKilo, ensure this address has zero kilos
        // getMyKilo is a view function
        uint256 kilosBefore = c.getMyKilo();
        // ensure precondition that caller has zero kilos so getFreeKilo will succeed
        if (kilosBefore != 0) {
            // If already has kilos, skip calling getFreeKilo and just assert relation holds vacuously
            uint256 claimed = c.claimedDrugs(address(this));
            uint256 drugsSince = c.getDrugsSinceLastCollect(address(this));
            uint256 myDrugs = c.getMyDrugs();
            // Assert that getMyDrugs equals claimedDrugs + drugsSinceLastCollect
            assert(myDrugs == claimed + drugsSince);
            return;
        }

        // call getFreeKilo which should grant STARTING_KILOS and set lastCollect
        c.getFreeKilo();

        // Read public values after the call
        uint256 kilosAfter = c.getMyKilo();
        uint256 claimedAfter = c.claimedDrugs(address(this));
        uint256 drugsSinceAfter = c.getDrugsSinceLastCollect(address(this));
        uint256 myDrugsAfter = c.getMyDrugs();
        uint256 DRUGS_TO_PRODUCE_1KILO = c.DRUGS_TO_PRODUCE_1KILO();
        uint256 STARTING_KILOS = c.STARTING_KILOS();

        // General property asserted:
        // 1) getFreeKilo increases kilos to exactly STARTING_KILOS when caller had zero before
        // 2) drugsSinceLastCollect is at most DRUGS_TO_PRODUCE_1KILO * STARTING_KILOS (the contract caps secondsPassed)
        // 3) getMyDrugs equals claimedDrugs + drugsSinceLastCollect
        assert(kilosAfter == STARTING_KILOS
               && drugsSinceAfter <= DRUGS_TO_PRODUCE_1KILO * STARTING_KILOS
               && myDrugsAfter == claimedAfter + drugsSinceAfter);
    }

    receive() external payable { }
}
